#include <stdint.h>
#include <string.h>

static const char UTF16_TEXT[] = "UTF16";
static const char INVALID_FORMAT_TEXT[] = "InvalidFormat";
static const char I1024_MIN_TEXT[] = "-";
static const char U1024_MAX_TEXT[] = "";

static int64_t checksum_unicode_text(const char *text) {
    size_t length = strlen(text);
    return (int64_t)length + (int64_t)text[0] + (int64_t)text[length - 1];
}

int main(void) {
    int64_t checksum = 0;

    for (int32_t i = 0; i < 50; i += 1) {
        checksum += checksum_unicode_text(UTF16_TEXT);
        checksum += checksum_unicode_text(INVALID_FORMAT_TEXT);
        checksum += checksum_unicode_text(I1024_MIN_TEXT);
        checksum += checksum_unicode_text(U1024_MAX_TEXT);
    }

    return checksum == 58350 ? 0 : 5;
}
